   169  otError NetworkData::GetNextExternalRoute(otNetworkDataIterator *aIterator,
   170                                            uint16_t               aRloc16,
   171                                            otExternalRouteConfig *aConfig)
   172  {
   173      otError             error = OT_ERROR_NOT_FOUND;
   174      NetworkDataIterator iterator(aIterator);
   175      NetworkDataTlv *    cur = reinterpret_cast<NetworkDataTlv *>(mTlvs + iterator.GetTlvOffset());
   176      NetworkDataTlv *    end = reinterpret_cast<NetworkDataTlv *>(mTlvs + mLength);
   177
   178      for (; cur < end; cur = cur->GetNext(), iterator.SetSubTlvOffset(0), iterator.SetEntryIndex(0))
   179      {
   180          PrefixTlv *     prefix;
   181          NetworkDataTlv *subCur;
   182          NetworkDataTlv *subEnd;
   183
   184          VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end, error = OT_ERROR_PARSE);
   185
   186          if (cur->GetType() != NetworkDataTlv::kTypePrefix)
   187          {
   188              continue;
   189          }
   190
   191          prefix = static_cast<PrefixTlv *>(cur);
   192
   193          subCur = reinterpret_cast<NetworkDataTlv *>(reinterpret_cast<uint8_t *>(prefix->GetSubTlvs()) +
   194                                                      iterator.GetSubTlvOffset());
   195          subEnd = cur->GetNext();
   196
   197          for (; subCur < subEnd; subCur = subCur->GetNext(), iterator.SetEntryIndex(0))
   198          {
   199              HasRouteTlv *hasRoute;
   200
   201              VerifyOrExit((subCur + 1) <= subEnd && subCur->GetNext() <= subEnd, error = OT_ERROR_PARSE);
   202
   203              if (subCur->GetType() != NetworkDataTlv::kTypeHasRoute)
   204              {
   205                  continue;
   206              }
   207
   208              hasRoute = static_cast<HasRouteTlv *>(subCur);
   209
   210              for (uint8_t index = iterator.GetEntryIndex(); index < hasRoute->GetNumEntries(); index++)
   211              {
   212                  if (aRloc16 == Mac::kShortAddrBroadcast || hasRoute->GetEntry(index)->GetRloc() == aRloc16)
   213                  {
   214                      HasRouteEntry *hasRouteEntry = hasRoute->GetEntry(index);
   215
   216                      memset(aConfig, 0, sizeof(*aConfig));
   217                      memcpy(&aConfig->mPrefix.mPrefix, prefix->GetPrefix(), BitVectorBytes(prefix->GetPrefixLength()));
   218                      aConfig->mPrefix.mLength      = prefix->GetPrefixLength();
   219                      aConfig->mPreference          = hasRouteEntry->GetPreference();
   220                      aConfig->mStable              = hasRoute->IsStable();
   221                      aConfig->mRloc16              = hasRouteEntry->GetRloc();
   222                      aConfig->mNextHopIsThisDevice = (hasRouteEntry->GetRloc() == GetNetif().GetMle().GetRloc16());
   223
   224                      iterator.SaveTlvOffset(cur, mTlvs);
   225                      iterator.SaveSubTlvOffset(subCur, prefix->GetSubTlvs());
   226                      iterator.SetEntryIndex(index + 1);
   227
